/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field SalesUnitId
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableSalesUnitId extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, SalesUnitId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    SalesTable salesTable;
    while select SalesUnitId from salesTable
        group by SalesUnitId
    {
        ret.add(salesTable.SalesUnitId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, SalesUnitId));
    qbr.value(queryValue(_value));
}
